#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "words.h"

static int by_count_then_word(const void *a, const void *b)
{
    const struct word_count *x = a;
    const struct word_count *y = b;
    if (x->count != y->count) return x->count > y->count ? -1 : 1;
    return strcmp(x->word, y->word);
}

int main(void)
{
    struct word_table table;
    if (!word_table_init(&table)) return 1;

    char word[64];
    size_t length = 0;
    long total = 0;
    int c;
    do {
        c = getchar();
        if (c != EOF && isalpha(c)) {
            if (length < sizeof word - 1) word[length++] = (char)tolower(c);
        } else if (length > 0) {
            word[length] = '\0';
            if (!word_table_add(&table, word)) {
                word_table_free(&table);
                return 1;
            }
            total++;
            length = 0;
        }
    } while (c != EOF);

    size_t count = 0;
    struct word_count *list = word_table_list(&table, &count);
    printf("%ld words, %zu different\n", total, count);
    if (list != NULL) {
        qsort(list, count, sizeof list[0], by_count_then_word);
        for (size_t i = 0; i < count && i < 10; i++) {
            printf("%-10s %d ", list[i].word, list[i].count);
            for (int k = 0; k < list[i].count && k < 40; k++) putchar('#');
            putchar('\n');
        }
        free(list);
    }
    word_table_free(&table);
    return 0;
}

