#ifndef WORDS_H
#define WORDS_H

#include <stdbool.h>
#include <stddef.h>

struct word_entry {
    char *word;
    int count;
    struct word_entry *next;
};

struct word_table {
    struct word_entry **buckets;
    size_t bucket_count;
    size_t size;
};

/* What word_table_list hands out: the words point into the table, so free the array
   (with free) before freeing the table. */
struct word_count {
    const char *word;
    int count;
};

bool word_table_init(struct word_table *t);
bool word_table_add(struct word_table *t, const char *word);   /* adds 1 to the word's count */
struct word_count *word_table_list(const struct word_table *t, size_t *count);
void word_table_free(struct word_table *t);

#endif

