#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "words.h"

static uint32_t hash(const char *s)
{
    uint32_t h = 2166136261u;
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        h ^= *p;
        h *= 16777619u;
    }
    return h;
}

bool word_table_init(struct word_table *t)
{
    t->bucket_count = 16;
    t->size = 0;
    t->buckets = calloc(t->bucket_count, sizeof *t->buckets);
    return t->buckets != NULL;
}

static void grow(struct word_table *t)
{
    size_t new_count = t->bucket_count * 2;
    struct word_entry **fresh = calloc(new_count, sizeof *fresh);
    if (fresh == NULL) return;          /* keep working with the old size */
    for (size_t i = 0; i < t->bucket_count; i++) {
        struct word_entry *e = t->buckets[i];
        while (e != NULL) {
            struct word_entry *next = e->next;
            size_t b = hash(e->word) % new_count;
            e->next = fresh[b];
            fresh[b] = e;
            e = next;
        }
    }
    free(t->buckets);
    t->buckets = fresh;
    t->bucket_count = new_count;
}

bool word_table_add(struct word_table *t, const char *word)
{
    size_t b = hash(word) % t->bucket_count;
    for (struct word_entry *e = t->buckets[b]; e != NULL; e = e->next) {
        if (strcmp(e->word, word) == 0) {
            e->count++;
            return true;
        }
    }
    struct word_entry *e = malloc(sizeof *e);
    if (e == NULL) return false;
    size_t length = strlen(word) + 1;
    e->word = malloc(length);
    if (e->word == NULL) {
        free(e);
        return false;
    }
    memcpy(e->word, word, length);
    e->count = 1;
    e->next = t->buckets[b];
    t->buckets[b] = e;
    t->size++;
    if (t->size > t->bucket_count * 3 / 4) grow(t);
    return true;
}

struct word_count *word_table_list(const struct word_table *t, size_t *count)
{
    *count = t->size;
    if (t->size == 0) return NULL;
    struct word_count *list = malloc(t->size * sizeof *list);
    if (list == NULL) {
        *count = 0;
        return NULL;
    }
    size_t n = 0;
    for (size_t i = 0; i < t->bucket_count; i++) {
        for (const struct word_entry *e = t->buckets[i]; e != NULL; e = e->next) {
            list[n].word = e->word;
            list[n].count = e->count;
            n++;
        }
    }
    return list;
}

void word_table_free(struct word_table *t)
{
    for (size_t i = 0; i < t->bucket_count; i++) {
        struct word_entry *e = t->buckets[i];
        while (e != NULL) {
            struct word_entry *next = e->next;
            free(e->word);
            free(e);
            e = next;
        }
    }
    free(t->buckets);
    t->buckets = NULL;
    t->bucket_count = 0;
    t->size = 0;
}
